                logger.warning("  token=%d '%s': %s", tid, tok_str, types)

        return dict(self.spec.event_type_first_token)

    def compile_role_constraints(self, tokenizer) -> dict[str, int]:
        """Build role -> first_token_id mapping with collision detection."""
        if not self.spec.all_roles:
            return {}

        if not self.spec.role_token_ids:
            self.compile_for_tokenizer(tokenizer)

        from collections import defaultdict
        first_token_groups: dict[int, list[str]] = defaultdict(list)

        for role in self.spec.all_roles:
            token_ids = self.spec.role_token_ids[role]
            first_id = token_ids[0]
            self.spec.role_first_token[role] = first_id
            first_token_groups[first_id].append(role)

        collision_groups = {tid: roles for tid, roles in first_token_groups.items() if len(roles) > 1}
        if collision_groups:
            n_colliding = sum(len(v) for v in collision_groups.values())
            logger.warning(
                "Role first-token collisions: %d/%d roles in %d groups.",
                n_colliding, len(self.spec.all_roles), len(collision_groups),
            )
            # Check same-event collisions (the ones that actually matter)
            same_event_problems = []
            for tid, roles in collision_groups.items():
                roles_set = set(roles)
                for evt_type, evt_data in self.spec.argument_constraints.items():
                    evt_roles = set(evt_data.keys())
                    overlap = roles_set & evt_roles
                    if len(overlap) > 1:
                        same_event_problems.append((evt_type, tid, sorted(overlap)))

            if same_event_problems:
                logger.warning(
                    "  %d event types have same-event role collisions (mask cannot disambiguate):",
                    len(same_event_problems),
                )
                for evt_type, tid, roles in same_event_problems:
                    tok_str = tokenizer.decode([tid]).strip()
                    logger.warning("    %s: token=%d '%s' -> %s", evt_type, tid, tok_str, roles)
            else:
                logger.info("  All role collisions are cross-event only (no practical impact).")

        return dict(self.spec.role_first_token)

    def build_processor(
        self,
        tokenizer,
        prompt_length: int = 0,
    ) -> list:
        """Assemble complete LogitsProcessor stack: [XGrammar, TypeConstraint].

        Returns list suitable for model.generate(logits_processor=...).
        """
        from .type_mask_processor import TypeConstraintProcessor

        self.compile_type_constraints(tokenizer)
        if self.spec.has_event_constraints:
            self.compile_event_type_constraints(tokenizer)
            self.compile_role_constraints(tokenizer)
        compiled_grammar = self.compile_xgrammar(tokenizer)

        import xgrammar as xgr

        processors = []
        processors.append(xgr.contrib.hf.LogitsProcessor(compiled_grammar))
        processors.append(TypeConstraintProcessor(self.spec, tokenizer, prompt_length))
        return processors


# ── Convenience ──────────────────────────────────────────────────────────

def compile_ontology(
    constraints_path: str | Path,
    tokenizer=None,
) -> tuple[ConstraintSpec, Optional["xgrammar.CompiledGrammar"]]:
    """One-call compilation: ontology JSON -> (ConstraintSpec, CompiledGrammar)."""
    compiler = OntologyCompiler(constraints_path)
    compiled_grammar = None

    if tokenizer is not None:
        compiler.compile_type_constraints(tokenizer)
        if compiler.spec.has_event_constraints:
            compiler.compile_event_type_constraints(tokenizer)
            compiler.compile_role_constraints(tokenizer)
        compiled_grammar = compiler.compile_xgrammar(tokenizer)

    return compiler.spec, compiled_grammar
